#include <iostream>
#include <sstream>
#include <string>
#include <vector>
#include <stdexcept>

struct Token {
    char clase;
    int valor;
};

Token leer_token(std::istringstream& entrada) {
    char actual = '?';
    while (entrada.get(actual)) {
        if (actual == ' ' || actual == '\t' || actual == '\n') {
            continue;
        }
        if (actual >= '0' && actual <= '9') {
            int valor = actual - '0';
            while (entrada.get(actual)) {
                if (actual >= '0' && actual <= '9') {
                    valor = valor * 10 + (actual - '0');
                    if (valor > 99) {
                        throw std::runtime_error("Numero fuera de dominio");
                    }
                } else {
                    entrada.putback(actual);
                    if (!entrada) {
                        throw std::runtime_error("No se pudo conservar el caracter");
                    }
                    return Token{'n', valor};
                }
            }
            if (entrada.bad() || !entrada.eof()) {
                throw std::runtime_error("Fallo del flujo");
            }
            return Token{'n', valor};
        }
        if (actual == '+' || actual == '-' || actual == '*'
                || actual == '/' || actual == '(' || actual == ')'
                || actual == ';') {
            return Token{actual, 0};
        }
        throw std::runtime_error("Caracter no admitido");
    }
    if (entrada.bad() || !entrada.eof()) {
        throw std::runtime_error("Fallo del flujo");
    }
    return Token{'f', 0};
}

bool token_valido(Token token) {
    if (token.clase == 'n') {
        return token.valor >= 0 && token.valor <= 99;
    }
    const bool signo = token.clase == '+' || token.clase == '-'
        || token.clase == '*' || token.clase == '/'
        || token.clase == '(' || token.clase == ')' || token.clase == ';';
    return token.valor == 0 && (signo || token.clase == 'f');
}

class Lector_tokens {
public:
    explicit Lector_tokens(const std::string& texto) : entrada_{texto} {}

    Token leer() {
        if (lleno_) {
            lleno_ = false;
            return guardado_;
        }
        return leer_token(entrada_);
    }

    void devolver(Token token) {
        if (lleno_) {
            throw std::runtime_error("Buffer ocupado");
        }
        if (!token_valido(token)) {
            throw std::runtime_error("Token invalido");
        }
        guardado_ = token;
        lleno_ = true;
    }

    bool descartar_operacion();

    bool tiene_pendiente() const {
        return lleno_;
    }

private:
    std::istringstream entrada_;
    bool lleno_ = false;
    Token guardado_{'f', 0};
};

bool Lector_tokens::descartar_operacion() {
    if (entrada_.bad()) {
        throw std::runtime_error("Flujo irrecuperable");
    }
    if (lleno_) {
        const Token pendiente = guardado_;
        lleno_ = false;
        if (pendiente.clase == ';') {
            return true;
        }
        if (pendiente.clase == 'f') {
            return false;
        }
    }
    entrada_.clear();
    char actual = '?';
    while (entrada_.get(actual)) {
        if (actual == ';') {
            return true;
        }
    }
    if (entrada_.bad() || !entrada_.eof()) {
        throw std::runtime_error("Fallo al recuperar");
    }
    return false;
}

int resultado_en_dominio(int candidato) {
    if (candidato < -100 || candidato > 100) {
        throw std::runtime_error("Resultado fuera de dominio");
    }
    return candidato;
}

int leer_expresion(Lector_tokens& lector, int profundidad);

int leer_unidad(Lector_tokens& lector, int profundidad) {
    if (profundidad > 8) {
        throw std::runtime_error("Anidamiento excesivo");
    }
    const Token token = lector.leer();
    if (token.clase == 'n') {
        return token.valor;
    }
    if (token.clase == '+') {
        return leer_unidad(lector, profundidad + 1);
    }
    if (token.clase == '-') {
        const int valor = leer_unidad(lector, profundidad + 1);
        return resultado_en_dominio(-valor);
    }
    if (token.clase == '(') {
        const int valor = leer_expresion(lector, profundidad + 1);
        const Token cierre = lector.leer();
        if (cierre.clase != ')') {
            lector.devolver(cierre);
            throw std::runtime_error("Se esperaba )");
        }
        return valor;
    }
    lector.devolver(token);
    throw std::runtime_error("Se esperaba una unidad");
}

