            const int derecha = leer_termino(lector, profundidad);
            izquierda = resultado_en_dominio(izquierda + derecha);

        } else if (token.clase == '-') {
            const int derecha = leer_termino(lector, profundidad);
            izquierda = resultado_en_dominio(izquierda - derecha);
        } else {
            lector.devolver(token);
